function groupedView(type){const groups=new Map();for(const s of songs){const name=type==='albums'?s.album:s.artist;if(!name)continue;const k=type==='albums'?JSON.stringify([s.artist,name]):name;if(!groups.has(k))groups.set(k,{name,artist:s.artist,cover:s.cover_path,count:0});groups.get(k).count++;}return [head(type==='albums'?'Albums':'Artists','Organized from the metadata in your library')+libraryTools()+`<div class="grid">${[...groups].sort((a,b)=>a[1].name.localeCompare(b[1].name)).map(([k,g])=>`<button class="card" data-act="groupopen" data-group-type="${type}" data-group-key="${esc(k)}"><div class="cv cover-single">${listArt(g.cover,g.name[0])}</div><b>${esc(g.name)}</b><small>${type==='albums'?esc(g.artist)+' · ':''}${g.count} songs</small></button>`).join('')||'<p class="sub">Add album details through a song’s menu to organize this view.</p>'}</div>`,null];}
