document.addEventListener('click',e=>{const t=e.target.closest('[data-act]');if(!t)return;const menu=t.closest('details.quiet-menu');if(menu)menu.removeAttribute('open');const a=t.dataset.act;if(a==='queue')openQueue();if(a==='bulk')bulkDialog();if(a==='commands')commands();if(a==='playermenu')playerMenu();if(a==='importplaylist')playlistImportDialog();if(a==='playbacktools')playbackTools();if(a==='advancedsettings')advancedSettings();if(a==='lyrictools')lyricTools();if(a==='songmenu'){const s=rowSong(t);if(s)songMenu(s);}if(a==='groupopen')go(t.dataset.groupType==='albums'?'album':'artist',t.dataset.groupKey);if(a==='moretracks'){const name=t.dataset.list;pageSizes.set(name,(pageSizes.get(name)||100)+100);render(true);}if(a==='selectiontoggle'){const on=$('main').classList.toggle('selecting');t.setAttribute('aria-pressed',String(on));if(!on){selection.clear();document.querySelectorAll('[data-select-song]').forEach(el=>{el.checked=false;el.closest('.song')?.classList.remove('selected');});}}if(a==='selectall'){(lists[t.dataset.list]||[]).forEach(s=>selection.add(s.id));render(true);}if(a==='selectionclear'){selection.clear();$('main').classList.remove('selecting');render(true);}if(a==='selectionplaylist')selection.size?choosePlaylist([...selection]):toast('Select songs first');if(a==='selectionqueue'){for(const id of selection){const s=songById(id);if(s)addQueue(s);}selection.clear();render(true);}if(a==='editplaylist'){const p=playlists.find(x=>x.id===t.dataset.id);if(p)editPlaylist(p,lists.pl||[]);}if(a==='exportplaylist'){const p=playlists.find(x=>x.id===t.dataset.id);if(p)exportPlaylist(p,lists.pl||[]);}if(a==='offline-remove')removeOffline(t.dataset.songId).catch(e=>toast(e.message));});
document.addEventListener('change',e=>{const id=e.target.dataset.selectSong;if(id){e.target.checked?selection.add(id):selection.delete(id);e.target.closest('.song')?.classList.toggle('selected',e.target.checked);if($('selectionCount'))$('selectionCount').textContent=selection.size+' selected';}});
document.addEventListener('click',e=>{document.querySelectorAll('details.quiet-menu[open]').forEach(menu=>{if(!menu.contains(e.target))menu.removeAttribute('open');});});
